#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
unsigned long recyclable = 0;
unsigned long other = 0;
bool full = false;
bool previousRecyclable = false;
bool previousOther = false;
bool previousButton = false;
unsigned long lastSample = 0;
unsigned long lastReport = 0;
bool haveDistance = false;
float distanceCm = 400.0f;

float readDistance() {
  digitalWrite(8, LOW);
  delayMicroseconds(2);
  digitalWrite(8, HIGH);
  delayMicroseconds(10);
  digitalWrite(8, LOW);
  unsigned long duration = pulseIn(9, HIGH, 30000UL);
  if (duration == 0) return -1.0f;
  return duration * 0.0343f / 2.0f;
}

void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(3, INPUT_PULLUP);
  pinMode(7, INPUT_PULLUP);
  pinMode(8, OUTPUT);
  pinMode(9, INPUT);
  pinMode(6, OUTPUT);
  pinMode(13, OUTPUT);
  digitalWrite(8, LOW);
  digitalWrite(13, LOW);
  Serial.begin(9600);
  display.setBrightness(7);
  display.showNumberDec(0);
  lastSample = millis() - 100UL;
}

void loop() {
  unsigned long now = millis();
  if (now - lastSample >= 100UL) {
    lastSample = now;
    float measured = readDistance();
    if (measured >= 0.0f) {
      distanceCm = measured;
      haveDistance = true;
      if (distanceCm < 20.0f) full = true;
    }
  }

  bool button = digitalRead(7) == LOW;
  bool a = digitalRead(2) == LOW;
  bool b = digitalRead(3) == LOW;
  if (button && !previousButton && haveDistance && distanceCm >= 20.0f) {
    recyclable = 0;
    other = 0;
    full = false;
  }
  previousButton = button;

  if (!full) {
    if (a && !previousRecyclable) ++recyclable;
    if (b && !previousOther) ++other;
  }
  previousRecyclable = a;
  previousOther = b;

  digitalWrite(13, full ? HIGH : LOW);
  if (full) {
    tone(6, 2000);
    if (lastReport == 0 || now - lastReport >= 1000UL) {
      Serial.println("empty bin needed");
      lastReport = now;
    }
  } else {
    noTone(6);
    lastReport = 0;
  }
  display.showNumberDec((recyclable + other) % 10000UL);
  delay(5);
}

#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
const unsigned long TARGET_PER_MINUTE = 60;
unsigned long startedAt, lastProductAt, lastReportAt;
unsigned long products = 0, stops = 0;
bool previousSensor = HIGH;
bool stopped = false;
bool buttonRaw = HIGH, buttonStable = HIGH;
unsigned long buttonChangedAt = 0;
uint8_t page = 1;

void showNumber(unsigned long n) {
  display.showNumberDec((int)(n > 9999 ? 9999 : n), false);
}

void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(3, INPUT_PULLUP);
  pinMode(7, INPUT_PULLUP);
  pinMode(6, OUTPUT);
  pinMode(13, OUTPUT);
  digitalWrite(13, LOW);
  Serial.begin(9600);
  display.setBrightness(5);
  startedAt = lastProductAt = millis();
  previousSensor = digitalRead(2);
}

void loop() {
  unsigned long now = millis();
  bool sensor = digitalRead(2);
  if (previousSensor == HIGH && sensor == LOW) {
    ++products;
    lastProductAt = now;
  }
  previousSensor = sensor;

  bool raw = digitalRead(7);
  if (raw != buttonRaw) {
    buttonRaw = raw;
    buttonChangedAt = now;
  }
  if (raw != buttonStable && now - buttonChangedAt >= 40) {
    buttonStable = raw;
    if (buttonStable == LOW) page = (page + 1) % 3;
  }

  bool manual = digitalRead(3) == LOW;
  bool idle = now - lastProductAt >= 30000UL;
  bool alarm = manual || idle;
  if (alarm && !stopped) {
    ++stops;
    Serial.print("STOP event="); Serial.print(stops);
    Serial.print(" time_ms="); Serial.print(now);
    Serial.println(manual ? " manual" : " idle");
    tone(6, 1800);
  }
  if (!alarm && stopped) noTone(6);
  stopped = alarm;
  digitalWrite(13, alarm ? HIGH : LOW);

  unsigned long elapsed = now - startedAt;
  float achievement = elapsed == 0 ? 0.0f :
      (float)products * 6000000.0f / ((float)TARGET_PER_MINUTE * elapsed);
  if (page == 0) showNumber(TARGET_PER_MINUTE);
  else if (page == 2) showNumber(stops);
  else if ((now / 2000UL) % 2 == 0) showNumber(products);
  else showNumber((unsigned long)(achievement + 0.5f));

  if (now - lastReportAt >= 1000UL) {
    lastReportAt = now;
    Serial.print("actual="); Serial.print(products);
    Serial.print(" achievement_percent="); Serial.print(achievement, 1);
    Serial.print(" stops="); Serial.println(stops);
  }
}

#include <Arduino.h>
#include <DHT.h>
#include <TM1637Display.h>
#include <math.h>
DHT dht(7,DHT11);
TM1637Display display(4,5);
float tempValue=NAN, distanceValue=NAN;
unsigned long epoch, nextTemp, nextDistance, alarmEpoch, lastReport;
uint8_t previousMask=0;
bool sounding=false;
void reportReasons(uint8_t mask){
  if(mask&1) Serial.println("ALARM_TEMP");
  if(mask&2) Serial.println("ALARM_DISTANCE");
}
void setup(){
  Serial.begin(9600);
  pinMode(8,OUTPUT); digitalWrite(8,LOW);
  pinMode(9,INPUT); pinMode(6,OUTPUT);
  noTone(6); dht.begin(); display.setBrightness(7); display.clear();
  epoch=millis(); nextTemp=epoch; nextDistance=epoch;
}
void loop(){
  unsigned long now=millis();
  if((long)(now-nextTemp)>=0){
    nextTemp=now+2000;
    tempValue=dht.readTemperature();
  }
  now=millis();
  if((long)(now-nextDistance)>=0){
    nextDistance=now+100;
    digitalWrite(8,LOW); delayMicroseconds(2);
    digitalWrite(8,HIGH); delayMicroseconds(10); digitalWrite(8,LOW);
    unsigned long echo=pulseIn(9,HIGH,25000UL);
    float cm=echo/58.0f;
    distanceValue=(echo && cm>=2.0f && cm<=400.0f)?cm:NAN;
  }
  now=millis();
  uint8_t mask=0;
  if(!isnan(tempValue) && tempValue>32.0f) mask|=1;
  if(!isnan(distanceValue) && distanceValue<15.0f) mask|=2;
  if(mask && !previousMask) alarmEpoch=now;
  if(mask && (mask!=previousMask || now-lastReport>=1000UL)){
    reportReasons(mask); lastReport=now;
  }
  bool shouldSound=mask && ((now-alarmEpoch)%1000UL<500UL);
  if(shouldSound!=sounding){
    if(shouldSound) tone(6,1000); else noTone(6);
    sounding=shouldSound;
  }
  previousMask=mask;
  float selected=(((now-epoch)/2000UL)%2==0)?tempValue:distanceValue;
  if(isnan(selected)) display.clear();
  else display.showNumberDec((int)roundf(selected),false);
}

#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 3);
bool automaticMode = true;
int lastRawButton = HIGH;
int stableButton = HIGH;
unsigned long rawChangedAt = 0;
unsigned long lastUpdate = 0;
bool firstUpdate = true;

void updateOutputs() {
  int temperatureRaw = analogRead(A1);
  int potentiometer = analogRead(A0);
  float temperatureC = temperatureRaw * (500.0f / 1023.0f);
  int pwm;
  int shown;
  if (automaticMode) {
    float requested = temperatureC * 255.0f / 100.0f;
    if (requested < 0.0f) requested = 0.0f;
    if (requested > 255.0f) requested = 255.0f;
    pwm = (int)(requested + 0.5f);
    shown = (int)(temperatureC + 0.5f);
  } else {
    pwm = (int)((potentiometer * 255L + 511L) / 1023L);
    shown = (int)((potentiometer * 10L + 511L) / 1023L);
  }
  analogWrite(5, pwm);
  display.showNumberDec(shown, false);
}

void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(5, OUTPUT);
  display.setBrightness(7);
  updateOutputs();
}

void loop() {
  unsigned long now = millis();
  int raw = digitalRead(2);
  if (raw != lastRawButton) {
    lastRawButton = raw;
    rawChangedAt = now;
  }
  if (raw != stableButton && now - rawChangedAt >= 40UL) {
    stableButton = raw;
    if (stableButton == LOW) {
      automaticMode = !automaticMode;
      updateOutputs();
    }
  }
  if (firstUpdate || now - lastUpdate >= 100UL) {
    firstUpdate = false;
    lastUpdate = now;
    updateOutputs();
  }
}

