#include <Arduino.h>
#include <TM1637Display.h>
#include <string.h>

TM1637Display display(4, 5);
unsigned long countOps = 0;
char command[48];
uint8_t commandLen = 0;
unsigned long lastByte = 0;
struct Button {
  uint8_t pin;
  bool raw;
  bool stable;
  unsigned long changed;
};
Button buttons[2] = {{2, HIGH, HIGH, 0}, {3, HIGH, HIGH, 0}};

void showCount() {
  display.showNumberDec((int)(countOps % 10000UL), false);
}
void operate(uint8_t operation) {
  if (operation == 3) {
    countOps = 0;
  } else {
    if (operation == 0) digitalWrite(13, HIGH);
    if (operation == 1) digitalWrite(13, LOW);
    if (operation == 2) tone(6, 1000, 200);
    ++countOps;
  }
  showCount();
}
void dispatch() {
  if (!commandLen) return;
  command[commandLen] = '\0';
  if (strcmp(command, "LIGHT_ON") == 0) operate(0);
  else if (strcmp(command, "LIGHT_OFF") == 0) operate(1);
  else if (strcmp(command, "BEEP") == 0) operate(2);
  else if (strcmp(command, "COUNT_RESET") == 0) operate(3);
  commandLen = 0;
}
void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(3, INPUT_PULLUP);
  pinMode(13, OUTPUT);
  pinMode(6, OUTPUT);
  digitalWrite(13, LOW);
  digitalWrite(6, LOW);
  Serial.begin(9600);
  display.setBrightness(7);
  showCount();
}
void loop() {
  while (Serial.available()) {
    char c = (char)Serial.read();
    lastByte = millis();
    if (c == '\n' || c == '\r') dispatch();
    else if (commandLen < sizeof(command) - 1) command[commandLen++] = c;
  }
  unsigned long now = millis();
  if (commandLen && now - lastByte >= 20) dispatch();
  for (uint8_t i = 0; i < 2; ++i) {
    Button &b = buttons[i];
    bool value = digitalRead(b.pin);
    if (value != b.raw) {
      b.raw = value;
      b.changed = now;
    }
    if (value != b.stable && now - b.changed >= 30) {
      b.stable = value;
      if (value == LOW) operate(i);
    }
  }
}

#include <Arduino.h>
#include <TM1637Display.h>
#include <math.h>

TM1637Display display(4, 5);
float currentTemperature = 0.0f;
float maximumTemperature = 0.0f;
bool haveTemperature = false;
bool historyActive = false;
unsigned long historyStarted = 0;
unsigned long lastSample = 0;
unsigned long lastReport = 0;
unsigned long buttonChanged = 0;
int rawButton = HIGH;
int stableButton = HIGH;

void sampleTemperature() {
  currentTemperature = analogRead(A1) * (500.0f / 1023.0f);
  if (!haveTemperature || currentTemperature > maximumTemperature) {
    maximumTemperature = currentTemperature;
  }
  haveTemperature = true;
}

void setup() {
  pinMode(2, INPUT_PULLUP);
  Serial.begin(9600);
  display.setBrightness(7);
  sampleTemperature();
}

void loop() {
  unsigned long now = millis();
  if (now - lastSample >= 100) {
    lastSample = now;
    sampleTemperature();
  }
  int reading = digitalRead(2);
  if (reading != rawButton) {
    rawButton = reading;
    buttonChanged = now;
  }
  if (now - buttonChanged >= 30 && stableButton != rawButton) {
    stableButton = rawButton;
    if (stableButton == LOW) {
      historyActive = true;
      historyStarted = now;
    }
  }
  if (historyActive && now - historyStarted >= 3000) {
    historyActive = false;
  }
  float shown = historyActive ? maximumTemperature : currentTemperature;
  display.showNumberDec((int)lroundf(shown), false);
  if (now - lastReport >= 250) {
    lastReport = now;
    Serial.print("Current: ");
    Serial.print(currentTemperature, 2);
    Serial.print(" Maximum: ");
    Serial.println(maximumTemperature, 2);
  }
}

#include <Arduino.h>

const uint8_t TRIG = 8, ECHO = 3, LED = 9, BUTTON = 2;
const int DARK_THRESHOLD = 500;
const float NEAR_CM = 100.0f;
bool forcedOn = false;
bool lastRaw = HIGH;
bool stableButton = HIGH;
unsigned long changedAt = 0;
unsigned long lastMeasurement = 0;
bool nearPerson = false;

void updateButton() {
  bool raw = digitalRead(BUTTON);
  unsigned long now = millis();
  if (raw != lastRaw) {
    lastRaw = raw;
    changedAt = now;
  }
  if (raw != stableButton && now - changedAt >= 30) {
    stableButton = raw;
    if (stableButton == LOW) forcedOn = !forcedOn;
  }
}

void measurePresence() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  unsigned long duration = pulseIn(ECHO, HIGH, 30000UL);
  float cm = duration * 0.0343f / 2.0f;
  nearPerson = duration != 0 && cm < NEAR_CM;
}

void setup() {
  pinMode(TRIG, OUTPUT);
  digitalWrite(TRIG, LOW);
  pinMode(ECHO, INPUT);
  pinMode(LED, OUTPUT);
  pinMode(BUTTON, INPUT_PULLUP);
  analogWrite(LED, 0);
}

void loop() {
  updateButton();
  unsigned long now = millis();
  if (now - lastMeasurement >= 70) {
    lastMeasurement = now;
    measurePresence();
  }
  bool dark = analogRead(A0) < DARK_THRESHOLD;
  analogWrite(LED, (forcedOn || (dark && nearPerson)) ? 255 : 0);
}

