    servo3.write(90);
  } else if (tensDigit >= 3 && tensDigit <= 5) {
    servo1.write(60);
    servo2.write(90);
    servo3.write(120);
  } else if (tensDigit >= 6 && tensDigit <= 9) {
    servo1.write(90);
    servo2.write(120);
    servo3.write(150);
  }
}

