  digitalWrite(BUZZER, LOW);
}

void loop() {
  unsigned long now = millis();
  if (sounding && now - startedAt >= 100UL) {
    noTone(BUZZER);
    digitalWrite(BUZZER, LOW);
    sounding = false;
  }
  if ((long)(now - nextStart) >= 0) {
    startedAt = now;
    nextStart += 1000UL;
    tone(BUZZER, 1000);
    sounding = true;
  }
}

